import styled from '@emotion/styled';
import { theme } from 'theme';

export const PHI_SECTION_SPACING = '24px';

export const StyledOverviewRoot = styled.div({
  boxSizing: 'border-box',
  display: 'flex',
  flexDirection: 'column',
  gap: PHI_SECTION_SPACING,
  width: '100%',
  margin: 0,
  padding: 0,

  '& [data-testid$="-total-phi-section-title"], & [data-testid$="-phi-performance-section-title"]':
    {
      fontFamily: theme.fonts.heading,
      fontSize: '32px',
      lineHeight: '120%',
    },

  '& [data-testid$="-total-phi-section-header"], & [data-testid$="-phi-performance-section-header"]':
    {
      minHeight: 'unset',
    },
});

export const StyledPhiSectionOuterBody = styled.div({
  boxSizing: 'border-box',
  width: '100%',
  minWidth: 0,
});

export const StyledPhiSectionInnerCard = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  minWidth: 0,
  padding: `${PHI_SECTION_SPACING} 0 ${PHI_SECTION_SPACING} ${PHI_SECTION_SPACING}`,
  boxSizing: 'border-box',
  backgroundColor: '#FFFFFF',
  border: '1px solid rgba(20, 20, 20, 0.16)',
  borderRadius: '12px',
  boxShadow: '0 1px 2px rgba(20, 20, 20, 0.08)',
  overflow: 'hidden',
});

export const StyledPhiOvertimeSubtitle = styled.h3({
  margin: 0,
  padding: 0,
  fontFamily: "'Work Sans', sans-serif",
  fontSize: '20px',
  fontWeight: 600,
  lineHeight: '120%',
  color: '#141414',
  flexShrink: 0,
});

export const StyledPhiOvertimeCardHeader = styled.header({
  display: 'flex',
  alignItems: 'center',
  width: 'auto',
  minHeight: '32px',
  margin: `0 0 0 -${PHI_SECTION_SPACING}`,
  padding: `0 0 12px ${PHI_SECTION_SPACING}`,
  boxSizing: 'border-box',
  borderBottom: '1px solid rgba(20, 20, 20, 0.16)',
});

export const StyledPhiOvertimeChartsGrid = styled.div({
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',
});
